using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class BFFFinalState {
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("B4 edit required");string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));string source="Assets/Afrer_Seconds/06.Data/AssetSources/B4_FullFloor_20261108.json";AssetDatabase.ImportAsset(source,ImportAssetOptions.ForceSynchronousImport);
  string temp="Assets/Temp/B4_FullFloor";if(Directory.Exists(temp)){string resolved=Path.GetFullPath(temp),expected=Path.GetFullPath(Path.Combine(Application.dataPath,"Temp/B4_FullFloor"));if(!string.Equals(resolved,expected,StringComparison.OrdinalIgnoreCase))throw new Exception("Unexpected temp path");AssetDatabase.DeleteAsset(temp);}
  if(s.isDirty){var copy=Path.Combine(Path.GetTempPath(),"B4_FinalCompare_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity");EditorSceneManager.SaveScene(s,copy,true);string disk=File.ReadAllText(s.path).TrimStart('\uFEFF').Replace("\r\n","\n"),memory=File.ReadAllText(copy).TrimStart('\uFEFF').Replace("\r\n","\n");if(disk!=memory)throw new Exception("Unreviewed changes backed up: "+copy);EditorSceneManager.SaveScene(s);}
  var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B4_"));var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));Selection.activeGameObject=root;
  if(SceneView.lastActiveSceneView){var v=SceneView.lastActiveSceneView;v.LookAt(new Vector3(0,-63,2),Quaternion.Euler(12,0,0),13,false,true);v.Repaint();}
  var data=new{scene=s.path,s.isDirty,Application.isPlaying,Application.runInBackground,playerRunInBackground=PlayerSettings.runInBackground,playerPosition=player.transform.position.ToString(),playerRotation=player.transform.eulerAngles.ToString(),lights=root.GetComponentsInChildren<Light>().Length,renderers=root.GetComponentsInChildren<Renderer>().Length,colliders=root.GetComponentsInChildren<Collider>().Length,provenanceGuid=AssetDatabase.AssetPathToGUID(source),placements=root.GetComponentsInChildren<Transform>().Where(t=>t.GetComponent<Renderer>()).Select(t=>new{name=t.name,position=t.position.ToString(),rotation=t.eulerAngles.ToString()}).ToArray()};File.WriteAllText(repo+"/Docs/검수/2026-11-08_B4_FullFloor/final_state.json",JsonConvert.SerializeObject(data,Formatting.Indented));if(data.isDirty||data.isPlaying||data.runInBackground||data.playerRunInBackground||data.lights!=261)throw new Exception("Unexpected final state");return new{data.scene,data.isDirty,data.isPlaying,data.runInBackground,data.playerPosition,data.lights,data.renderers,data.colliders};}
}
